  const farea = fields.area || '';
  const fwidth = fields.width || '';
  const fdepth = fields.depth || '';
  const fcolor = fields.color || '';

  // Datos correspondientes
  const vheight = round(safe(data?.[fheight]));
  const varea = round(safe(data?.[farea]));
  const vwidth = round(safe(data?.[fwidth]));
  const vdepth = round(safe(data?.[fdepth]));
  const vcolor = safe(data?.[fcolor]);

  // Texto final
  let processedTemplate = isQuarter ? '{name}' : template;
  processedTemplate = processedTemplate.replaceAll('{name}', name).replaceAll('{height}', vheight).replaceAll('{area}', varea).replaceAll('{width}', vwidth).replaceAll('{depth}', vdepth).replaceAll('{color}', vcolor).replaceAll('{fheight}', fheight).replaceAll('{farea}', farea).replaceAll('{fwidth}', fwidth).replaceAll('{fdepth}', fdepth).replaceAll('{fcolor}', fcolor);
  const knownPlaceholders = new Set(['name', 'height', 'area', 'width', 'depth', 'color', 'fheight', 'farea', 'fwidth', 'fdepth', 'fcolor']);
